export class ForwardSurface {
  constructor(private readonly _gateway: BridgethingGateway) {}

  /** Subscribe to `Forward::Text` across all peers. */
  onText(handler: (deviceId: string, msg: string) => void): () => void {
    return this._gateway.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      if (inner.encoding !== 'text') return;
      handler(event.deviceId, inner.data);
    });
  }

  /** Subscribe to `Forward::Json` across all peers. */
  onJson(handler: (deviceId: string, msg: unknown) => void): () => void {
    return this._gateway.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      if (inner.encoding !== 'json') return;
      handler(event.deviceId, inner.data);
    });
  }

  /** Subscribe to `Forward::Binary` across all peers. */
  onBinary(handler: (deviceId: string, msg: Uint8Array) => void): () => void {
    return this._gateway.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      if (inner.encoding !== 'binary') return;
      handler(event.deviceId, inner.data);
    });
  }

  /** Exhaustive subscribe over all inbound `Forward` variants. */
  subscribe(handlers: ForwardInboundHandlers): () => void {
    return this._subscribe(handlers, false);
  }

  /** Same as `subscribe` but every handler is optional. */
  subscribePartial(handlers: Partial<ForwardInboundHandlers>): () => void {
    return this._subscribe(handlers, true);
  }

  private _subscribe(handlers: Partial<ForwardInboundHandlers>, partial: boolean): () => void {
    return this._gateway.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      switch (inner.encoding) {
        case 'text': {
          handlers.text?.(event.deviceId, inner.data);
          return;
        }
        case 'json': {
          handlers.json?.(event.deviceId, inner.data);
          return;
        }
        case 'binary': {
          handlers.binary?.(event.deviceId, inner.data);
          return;
        }
        default: {
          if (!partial) this._gateway.logger.warn('Forward: no handler for inner', inner);
          return;
        }
      }
    });
  }
}

